questionvariables.text:
validate_numeric(ex) := block([sx], sx: ev(ex, simp), if listofvars(ex) = [] and freeof(%i, sx) then "" else "Type a number in each box, not a letter.");
Srx: matrix([1,0],[0,-1]); Sry: matrix([-1,0],[0,1]); Sryx: matrix([0,1],[1,0]); Srmyx: matrix([0,-1],[-1,0]);
Sr90: matrix([0,-1],[1,0]); Sr180: matrix([-1,0],[0,-1]); Sr270: matrix([0,1],[-1,0]);
symkeys: ["rx","ry","ryx","rmyx","r90","r180","r270"];
symmats: [Srx,Sry,Sryx,Srmyx,Sr90,Sr180,Sr270];
sm(k) := symmats[sublist_indices(symkeys, lambda([u], u=k))[1]];
sn(k) := sublist_indices(symkeys, lambda([u], u=k))[1];
skey(A) := block([j], j: sublist_indices(symmats, lambda([u], is(u=A))), if j=[] then "none" else symkeys[j[1]]);
/* Design: find-the-mistake pattern. Source: original. er 2: step 2 uses the partner matrix of the second transformation; er 3: step 3 writes A x B; er 5: step 5 multiplies by the transpose. Step 1 is never the mistake. For every entry the partner matrix times A equals A x B, so Achieng's matrix for er 2 and er 3 is A x B: PRT2 needs one node for it. */
elist: [["r90","rmyx",[3,-3],3],["ryx","ry",[1,2],2],["rx","rmyx",[1,-1],5],["ryx","r90",[-3,5],3],["ry","ryx",[1,2],5],["ryx","rx",[3,-1],5],["rmyx","r90",[-2,2],2],["rx","r90",[1,-1],2],["rmyx","ry",[-2,2],3],["ry","rmyx",[1,1],5]];
ix: 1+rand(10);
t1: elist[ix][1]; t2: elist[ix][2]; k: elist[ix][3]; er: elist[ix][4];
partner: ["ry","rx","rmyx","ryx","r270","rmyx","r90"];
A: sm(t1); B: sm(t2);
Bs: if er=2 then sm(partner[sn(t2)]) else B;
Ps: if er=3 then A.Bs else Bs.A;
kc: transpose(matrix(k));
img: list_matrix_entries(if er=5 then transpose(Ps).kc else Ps.kc);
ta: B.A; tk: list_matrix_entries(ta.kc); AB: A.B;
opts: [["s1",false,"Step 1"],["s2",is(er=2),"Step 2"],["s3",is(er=3),"Step 3"],["s4",false,"Step 4"],["s5",is(er=5),"Step 5"]];
tas: first(mcq_correct(opts));
wst: if er=2 then "s3" else "s2";
tw: ta+matrix([1,0],[0,0]); tw2: ta+matrix([0,0],[0,1]);
badm: matrix([q,0],[0,1]);
